//! Durable task trees and metric history from the official progress protocol.
use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::protocol::Progress;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct MetricDefinition {
    pub meaning: String,
    pub unit: String,
}

/// This reference is generated by `tomojax.wire.metrics.table()`. Keeping its
/// contents as the source avoids a second, hand-maintained scientific unit map.
pub fn metric_registry() -> &'static BTreeMap<String, MetricDefinition> {
    static REGISTRY: OnceLock<BTreeMap<String, MetricDefinition>> = OnceLock::new();
    REGISTRY.get_or_init(|| {
        include_str!("../../docs/progress-metrics.md")
            .lines()
            .filter_map(|line| {
                let cells: Vec<_> = line.split('|').map(str::trim).collect();
                if cells.len() != 5 || !cells[1].starts_with('`') {
                    return None;
                }
                Some((
                    cells[1].trim_matches('`').to_owned(),
                    MetricDefinition {
                        meaning: cells[2].to_owned(),
                        unit: cells[3].to_owned(),
                    },
                ))
            })
            .collect()
    })
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum TaskState {
    Running,
    Paused,
    Done,
    Failed,
    Cancelled,
}
impl TaskState {
    pub fn active(self) -> bool {
        matches!(self, Self::Running | Self::Paused)
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MetricSample {
    pub step: u64,
    pub time: f64,
    /// Nulls remain explicit gaps; categories remain strings.
    pub value: Value,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct MetricHistory {
    pub name: String,
    pub meaning: Option<String>,
    /// Unknown metrics have no guessed unit.
    pub unit: Option<String>,
    pub samples: Vec<MetricSample>,
}
impl MetricHistory {
    fn new(name: &str) -> Self {
        let definition = metric_registry().get(name);
        Self {
            name: name.into(),
            meaning: definition.map(|definition| definition.meaning.clone()),
            unit: definition.map(|definition| definition.unit.clone()),
            samples: Vec::new(),
        }
    }
    fn push(&mut self, step: u64, time: f64, value: Value) {
        // Preserve every observed sample, including repeated step numbers and
        // nulls. Plot thinning belongs to presentation, never the job record.
        self.samples.push(MetricSample { step, time, value });
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TaskProgress {
    /// Task IDs restart for each worker request, including open/run/save phases.
    pub request: String,
    pub id: u64,
    pub parent: Option<u64>,
    pub name: String,
    pub label: String,
    pub unit: String,
    pub done: u64,
    pub total: Option<u64>,
    pub started: f64,
    pub time: f64,
    pub finished: Option<f64>,
    /// Worker estimate in active seconds. Pausing must not count it down.
    pub eta: Option<f64>,
    pub state: TaskState,
    pub devices: Vec<String>,
    pub metrics: BTreeMap<String, MetricHistory>,
}
impl TaskProgress {
    pub fn fraction(&self) -> Option<f32> {
        self.total
            .filter(|total| *total > 0)
            .map(|total| (self.done as f64 / total as f64).clamp(0., 1.) as f32)
    }
    pub fn title(&self) -> &str {
        if self.label.is_empty() {
            &self.name
        } else {
            &self.label
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct JobNote {
    pub request: String,
    pub task: Option<u64>,
    pub time: f64,
    pub level: String,
    pub message: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct JobProgress {
    #[serde(default)]
    pub tasks: Vec<TaskProgress>,
    #[serde(default)]
    pub notes: Vec<JobNote>,
}

impl JobProgress {
    pub fn task(&self, request: &str, id: u64) -> Option<&TaskProgress> {
        self.tasks
            .iter()
            .find(|task| task.request == request && task.id == id)
    }

    fn task_mut(&mut self, request: &str, id: u64) -> Option<&mut TaskProgress> {
        self.tasks
            .iter_mut()
            .find(|task| task.request == request && task.id == id)
    }

    /// The most recently started active task. Ancestors retain their own
    /// denominator; child percentages are never averaged into fabricated totals.
    pub fn current(&self) -> Option<&TaskProgress> {
        self.tasks.iter().rev().find(|task| task.state.active())
    }

    pub fn apply(&mut self, request: &str, record: &Progress) {
        match record {
            Progress::Started {
                task,
                time,
                parent,
                name,
                label,
                total,
                unit,
                ..
            } => {
                if self.task(request, *task).is_none() {
                    self.tasks.push(TaskProgress {
                        request: request.into(),
                        id: *task,
                        parent: *parent,
                        name: name.clone(),
                        label: label.clone(),
                        unit: unit.clone(),
                        done: 0,
                        total: *total,
                        started: *time,
                        time: *time,
                        finished: None,
                        eta: None,
                        state: TaskState::Running,
                        devices: Vec::new(),
                        metrics: BTreeMap::new(),
                    });
                }
            }
            Progress::Placed {
                task,
                time,
                devices,
                ..
            } => {
                if let Some(task) = self.task_mut(request, *task) {
                    task.time = *time;
                    task.devices.clone_from(devices);
                }
            }
            Progress::Advanced {
                task,
                time,
                done,
                total,
                metrics,
                eta,
                ..
            } => {
                if let Some(task) = self.task_mut(request, *task) {
                    task.time = *time;
                    task.done = *done;
                    task.total = *total;
                    task.eta = *eta;
                    for (name, value) in metrics {
                        task.metrics
                            .entry(name.clone())
                            .or_insert_with(|| MetricHistory::new(name))
                            .push(*done, *time, value.clone());
                    }
                }
            }
            Progress::Finished {
                task, time, status, ..
            } => {
                if let Some(task) = self.task_mut(request, *task) {
                    task.time = *time;
                    task.finished = Some(*time);
                    task.eta = None;
                    task.state = match status.as_str() {
                        "done" => TaskState::Done,
                        "cancelled" => TaskState::Cancelled,
                        _ => TaskState::Failed,
                    };
                }
            }
            Progress::Paused { task, time, .. } | Progress::Resumed { task, time, .. } => {
                if let Some(task) = self.task_mut(request, *task) {
                    task.time = *time;
                    task.state = if matches!(record, Progress::Paused { .. }) {
                        TaskState::Paused
                    } else {
                        TaskState::Running
                    };
                }
            }
            Progress::Note {
                task,
                time,
                level,
                message,
                ..
            } => self.notes.push(JobNote {
                request: request.into(),
                task: *task,
                time: *time,
                level: level.clone(),
                message: message.clone(),
            }),
            Progress::Preview { .. } => {}
        }
    }

    /// Start order is retained within each sibling group. Unknown parents remain
    /// visible at the root, and malformed cycles cannot hang the renderer.
    pub fn tree(&self) -> Vec<(usize, &TaskProgress)> {
        fn walk<'a>(
            telemetry: &'a JobProgress,
            index: usize,
            depth: usize,
            visited: &mut BTreeSet<usize>,
            rows: &mut Vec<(usize, &'a TaskProgress)>,
        ) {
            if !visited.insert(index) {
                return;
            }
            let task = &telemetry.tasks[index];
            rows.push((depth, task));
            for (child_index, child) in telemetry.tasks.iter().enumerate() {
                if child.request == task.request && child.parent == Some(task.id) {
                    walk(telemetry, child_index, depth + 1, visited, rows);
                }
            }
        }
        let mut rows = Vec::new();
        let mut visited = BTreeSet::new();
        for (index, task) in self.tasks.iter().enumerate() {
            if task
                .parent
                .is_none_or(|parent| self.task(&task.request, parent).is_none())
            {
                walk(self, index, 0, &mut visited, &mut rows);
            }
        }
        for index in 0..self.tasks.len() {
            if !visited.contains(&index) {
                walk(self, index, 0, &mut visited, &mut rows);
            }
        }
        rows
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn event(value: Value) -> Progress {
        serde_json::from_value(value).unwrap()
    }
    fn start(id: u64, parent: Option<u64>, name: &str, total: Option<u64>) -> Progress {
        event(
            json!({"event":"started","schema":2,"task":id,"time":0.,"parent":parent,
            "name":name,"label":name,"total":total,"unit":"iterations"}),
        )
    }
    #[test]
    fn nested_progress_retains_parent_totals_and_request_scope() {
        let mut progress = JobProgress::default();
        progress.apply("open", &start(1, None, "Load scan", None));
        progress.apply("run", &start(1, None, "Joint alignment", Some(4)));
        progress.apply("run", &start(2, Some(1), "Level 1", Some(20)));
        progress.apply(
            "run",
            &event(json!({"event":"advanced","schema":2,"task":2,
            "time":3.,"done":5,"total":20,"metrics":{},"eta":9.})),
        );
        assert_eq!(
            progress
                .tree()
                .iter()
                .map(|(depth, task)| (*depth, task.request.as_str(), task.id))
                .collect::<Vec<_>>(),
            [(0, "open", 1), (0, "run", 1), (1, "run", 2)]
        );
        assert_eq!(progress.task("run", 1).unwrap().total, Some(4));
        assert_eq!(progress.current().unwrap().fraction(), Some(0.25));
        progress.apply(
            "run",
            &event(json!({"event":"paused","schema":2,"task":2,"time":3.1})),
        );
        assert_eq!(progress.current().unwrap().eta, Some(9.));
        progress.apply(
            "run",
            &event(json!({"event":"finished","schema":2,"task":2,"time":4.,"status":"done"})),
        );
        assert_eq!(progress.current().unwrap().id, 1);
        assert_eq!(progress.task("run", 2).unwrap().eta, None);
    }
    #[test]
    fn official_units_sparse_alignment_samples_and_warnings_survive_reload() {
        let mut progress = JobProgress::default();
        progress.apply("run", &start(1, None, "Align", Some(10)));
        for (step, objective) in [(1, json!(8.)), (3, Value::Null), (4, json!(4.))] {
            progress.apply("run", &event(json!({"event":"advanced","schema":2,"task":1,"time":step as f64,
                "done":step,"total":10,"metrics":{"objective":objective,"pose_step_rms":0.2,"cg_status":"budget","future_metric":7},"eta":null})));
        }
        progress.apply("run", &event(json!({"event":"note","schema":2,"task":null,"time":4.1,"level":"warning","message":"Uncalibrated pixel lengths"})));
        let reopened: JobProgress =
            serde_json::from_str(&serde_json::to_string(&progress).unwrap()).unwrap();
        let metrics = &reopened.tasks[0].metrics;
        assert_eq!(
            metrics["objective"].unit.as_deref(),
            Some("objective units")
        );
        assert_eq!(
            metrics["pose_step_rms"].unit.as_deref(),
            Some("working pixels")
        );
        assert_eq!(metrics["cg_status"].unit.as_deref(), Some("category"));
        assert_eq!(metrics["future_metric"].unit, None);
        assert_eq!(
            metrics["objective"]
                .samples
                .iter()
                .map(|sample| sample.step)
                .collect::<Vec<_>>(),
            [1, 3, 4]
        );
        assert!(metrics["objective"].samples[1].value.is_null());
        assert_eq!(reopened.notes[0].level, "warning");
        assert_eq!(reopened.notes[0].task, None);
        assert_eq!(reopened.notes[0].message, "Uncalibrated pixel lengths");
    }
    #[test]
    fn long_metric_history_is_retained_for_the_job_record() {
        let mut history = MetricHistory::new("loss");
        for step in 0..2050 {
            history.push(step, step as f64, json!(step));
        }
        assert_eq!(history.samples.len(), 2050);
        assert_eq!(history.samples.first().unwrap().step, 0);
        assert_eq!(history.samples.last().unwrap().step, 2049);
        history.push(2049, 2050., Value::Null);
        assert_eq!(history.samples.len(), 2051);
        assert!(history.samples.last().unwrap().value.is_null());
        assert_eq!(history.samples[2049].value, json!(2049));
    }

    #[test]
    #[ignore = "compares the embedded registry against the installed official Python registry"]
    fn metric_registry_matches_the_official_worker_definitions() {
        let python = std::env::var_os("TOMOJAX_TEST_PYTHON").expect("set TOMOJAX_TEST_PYTHON");
        let output = std::process::Command::new(python).args(["-c",
            "import json; from tomojax.wire.metrics import Metric; print(json.dumps({m.name: {'meaning':m.value[0], 'unit':m.value[1]} for m in Metric}))"
        ]).output().unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let registry: BTreeMap<String, MetricDefinition> =
            serde_json::from_slice(&output.stdout).unwrap();
        assert_eq!(&registry, metric_registry());
    }
}
